-- 0149 actor-owned intent cancellation. Synthetic SQL session/MFA fixture only; NOT real Auth acceptance.
begin;
-- The ordinary SQL harness has minimal auth.users only. This transaction-scoped
-- schema stand-in is created ONLY when absent; real GoTrue acceptance is separate.
do $fixture149_auth$declare prior text:=current_user;begin
 if to_regclass('auth.sessions') is null then
  set local role postgres;
  create table auth.sessions(id uuid primary key,user_id uuid not null references auth.users(id),not_after timestamptz);
  execute format('set local role %I',prior);
 end if;
end $fixture149_auth$;
create function pg_temp.id(n int) returns uuid language sql immutable as $$select ('99143000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid$$;
create function pg_temp.ok(v boolean,m text) returns void language plpgsql as $$begin if v is distinct from true then raise exception 'ASSERTION: %',m;end if;end$$;
insert into auth.users(id,email) select pg_temp.id(n),'custody-'||n||'@example.invalid' from generate_series(1,5)n;
insert into public.users(id,email,is_axiom_internal) select pg_temp.id(n),'custody-'||n||'@example.invalid',n in(2,3) from generate_series(1,5)n;
insert into public.tenants(id,slug,name) values(pg_temp.id(11),'custody-143-a','Synthetic custody A'),(pg_temp.id(12),'custody-143-b','Synthetic custody B');
insert into public.tenant_users(tenant_id,user_id,role) values(pg_temp.id(11),pg_temp.id(1),'owner'),(pg_temp.id(11),pg_temp.id(2),'founder'),(pg_temp.id(11),pg_temp.id(3),'axiom_analyst'),(pg_temp.id(11),pg_temp.id(4),'viewer'),(pg_temp.id(12),pg_temp.id(5),'owner');
insert into auth.sessions(id,user_id,not_after) select pg_temp.id(100+n),pg_temp.id(n),null from generate_series(1,5)n;
insert into public.user_mfa_factors(id,user_id,factor_type,status,secret_encrypted) select pg_temp.id(40+n),pg_temp.id(n),'totp','active','synthetic-sealed' from generate_series(1,5)n;
insert into public.workload_identities(id,tenant_id,agent_name,spiffe_id,status) values(pg_temp.id(31),pg_temp.id(11),'parikshan','spiffe://local.axiom/agent/parikshan','active');
create function pg_temp.policy() returns jsonb language sql as $$select jsonb_build_object('version',1,'policyId',pg_temp.id(21),'tenantId',pg_temp.id(11),'mode','operator_managed','nominatedOperatorId',pg_temp.id(3),'targetWorkloadId',pg_temp.id(31),'servicePrincipals',jsonb_build_object('producer','spiffe://local.axiom/service/assessment-dispatch-producer','controller','spiffe://local.axiom/controller/assessment'),'validity',jsonb_build_object('kind','until_revoked','reviewDueAt',1),'actionClass','assessment_dispatch_key_custody','keyPolicy',jsonb_build_object('primary','axiom-local-dispatch://'||pg_temp.id(11)||'/'||pg_temp.id(21)||'/versions/1','readable',jsonb_build_array('axiom-local-dispatch://'||pg_temp.id(11)||'/'||pg_temp.id(21)||'/versions/1')),'keyPolicySha256','2e67deedbb81f6897d5f5a48a76734faaf79e6e86bd54285f03d9114a4e0f30b','deploymentBindingSha256',repeat('b',64),'reason','Explicit local custody limitation','acceptedLimitations',jsonb_build_array('hardware_backing_unverified'),'statutoryComplianceAsserted',false,'ownershipVerified',false)$$;
-- Above key-policy fingerprint is independently generated by frozen TS LocalKeyPolicy.
select pg_temp.ok(controller_security.local143_policy(controller_security.canonical_questionnaire_json(pg_temp.policy()))=pg_temp.policy(),'TS key fingerprint matches SQL canonical derivation');
-- Syntax parity only: actual issuer/peer must still pin the configured trusted principal.
do $$declare d text;k text;v jsonb;path text;begin
 foreach d in array array['..','.local','local.','-local','local-','a..b','LOCAL','a b',repeat('a',256)] loop
  foreach k in array array['producer','controller'] loop
   path:=case k when 'producer' then 'service/assessment-dispatch-producer' else 'controller/assessment' end;
   v:=jsonb_set(pg_temp.policy(),array['servicePrincipals',k],to_jsonb('spiffe://'||d||'/'||path));
   begin perform controller_security.local143_policy(controller_security.canonical_questionnaire_json(v));
    raise exception 'invalid custody service domain accepted';
   exception when invalid_parameter_value then null;end;
  end loop;
 end loop;
 foreach d in array array['a','local.axiom','a-b.c',repeat('a',255)] loop
  v:=jsonb_set(jsonb_set(pg_temp.policy(),'{servicePrincipals,producer}',to_jsonb('spiffe://'||d||'/service/assessment-dispatch-producer')),'{servicePrincipals,controller}',to_jsonb('spiffe://'||d||'/controller/assessment'));
  perform pg_temp.ok(controller_security.local143_policy(controller_security.canonical_questionnaire_json(v))=v,'canonical service domain accepted');
 end loop;
end$$;
create function pg_temp.request(k int,transition text,previous uuid default null) returns text language sql as $$select controller_security.canonical_questionnaire_json(jsonb_build_object('version',1,'operationKey',pg_temp.id(k),'transition',transition,'policyText',controller_security.canonical_questionnaire_json(pg_temp.policy()),'policySha256',encode(sha256(convert_to(controller_security.canonical_questionnaire_json(pg_temp.policy()),'UTF8')),'hex'),'previousEventId',previous,'nextReviewDueAt',case when transition='review' then to_jsonb(floor(extract(epoch from clock_timestamp())*1000)::bigint+86400000) else 'null'::jsonb end,'reason','Explicit synthetic custody decision','confirmed',true))$$;
create function pg_temp.challenge(actor int,request_text text) returns uuid language plpgsql as $$declare c uuid:=gen_random_uuid();r jsonb:=request_text::jsonb;binding text;begin
 binding:=encode(sha256(convert_to(controller_security.canonical_questionnaire_json(jsonb_build_array('axiom.local-custody.transition',1,pg_temp.id(11)::text,pg_temp.id(actor)::text,pg_temp.id(100+actor)::text,encode(sha256(convert_to(request_text,'UTF8')),'hex'))),'UTF8')),'hex');
 insert into public.mfa_challenges(id,user_id,tenant_id,factor_id,purpose,bound_resource_ref,bound_payload_sha256,created_at,expires_at,satisfied_at,consumed_at,consumed_for,satisfied_with) values(c,pg_temp.id(actor),pg_temp.id(11),pg_temp.id(40+actor),'local_custody_policy',r->>'operationKey',binding,clock_timestamp()-interval '2 seconds',clock_timestamp()+interval '4 minutes 50 seconds',clock_timestamp()-interval '1 second',clock_timestamp(),r->>'operationKey','totp');return c;
end$$;
create function pg_temp.write(request_text text,actor int,challenge uuid default null) returns jsonb language plpgsql as $$declare c uuid:=coalesce(challenge,pg_temp.challenge(actor,request_text));v jsonb;prior text:=current_user;begin
 set local role human_action_writer;v:=public.record_local_custody_policy_event(pg_temp.id(11),pg_temp.id(actor),pg_temp.id(100+actor),request_text,c);execute format('set local role %I',prior);return v;
 exception when others then execute format('set local role %I',prior);raise;end$$;
create function pg_temp.refused(request_text text,actor int,code text default '42501',challenge uuid default null) returns void language plpgsql as $$declare n bigint;begin
 select count(*) into n from public.audit_ledger;
 begin perform pg_temp.write(request_text,actor,challenge);set constraints all immediate;exception when others then if sqlstate=code then perform pg_temp.ok((select count(*)=n from public.audit_ledger),'refusal leaves ledger unchanged');return;end if;raise;end;
 raise exception 'unexpected custody authorization';end$$;

create function pg_temp.cancellation(k int,original text,reason text default 'Abandon exact stale intent') returns text language sql as $$select controller_security.canonical_questionnaire_json(jsonb_build_object('version',1,'operationKey',pg_temp.id(k),'originalRequestText',original,'reason',reason,'confirmed',true))$$;
create function pg_temp.cancel_challenge(actor int,body text) returns uuid language plpgsql as $$declare c uuid:=gen_random_uuid();r jsonb:=body::jsonb;binding text;begin
 binding:=encode(sha256(convert_to(controller_security.canonical_questionnaire_json(jsonb_build_array('axiom.local-custody.cancel',1,pg_temp.id(11)::text,pg_temp.id(actor)::text,pg_temp.id(100+actor)::text,encode(sha256(convert_to(body,'UTF8')),'hex'))),'UTF8')),'hex');
 insert into public.mfa_challenges(id,user_id,tenant_id,factor_id,purpose,bound_resource_ref,bound_payload_sha256,created_at,expires_at,satisfied_at,consumed_at,consumed_for,satisfied_with) values(c,pg_temp.id(actor),pg_temp.id(11),pg_temp.id(40+actor),'local_custody_policy',r->>'operationKey',binding,clock_timestamp()-interval '2 seconds',clock_timestamp()+interval '4 minutes 50 seconds',clock_timestamp()-interval '1 second',clock_timestamp(),r->>'operationKey','totp');return c;
end$$;
create function pg_temp.cancel(body text,actor int,challenge uuid default null) returns jsonb language plpgsql as $$declare c uuid:=coalesce(challenge,pg_temp.cancel_challenge(actor,body));v jsonb;prior text:=current_user;begin
 set local role human_action_writer;v:=public.record_local_custody_policy_cancellation(pg_temp.id(11),pg_temp.id(actor),pg_temp.id(100+actor),body,c);execute format('set local role %I',prior);return v;
 exception when others then execute format('set local role %I',prior);raise;end$$;
create function pg_temp.cancel_refused(body text,actor int,code text,challenge uuid default null) returns void language plpgsql as $$declare n bigint;begin
 select count(*) into n from public.audit_ledger;
 begin perform pg_temp.cancel(body,actor,challenge);set constraints all immediate;exception when others then if sqlstate=code then perform pg_temp.ok((select count(*)=n from public.audit_ledger),'refusal leaves ledger unchanged');return;end if;raise;end;
 raise exception 'unexpected custody cancellation';end$$;
-- @local149_fixture_prefix_end
create temporary table local149_saved(kind text primary key,body text,v jsonb);
insert into local149_saved values('original',pg_temp.request(61,'request'),null);
insert into local149_saved select 'cancel',pg_temp.cancellation(161,body),null from local149_saved where kind='original';
select pg_temp.cancel_refused((select body from local149_saved where kind='cancel'),4,'42501');
select pg_temp.cancel_refused((select body from local149_saved where kind='cancel'),5,'42501');
select pg_temp.cancel_refused((select body from local149_saved where kind='cancel'),1,'42501',pg_temp.challenge(1,(select body from local149_saved where kind='original')));
update local149_saved set v=pg_temp.cancel(body,1) where kind='cancel';
set constraints all immediate;set constraints all deferred;
select pg_temp.ok((select v->>'state'='cancelled' from local149_saved where kind='cancel'),'cancel-first positive');
select pg_temp.ok((select count(*)=0 from public.local_custody_policy_versions),'cancel creates no policy');
select pg_temp.ok((select count(*)=0 from public.local_custody_policy_heads),'cancel changes no head');
select pg_temp.refused((select body from local149_saved where kind='original'),1,'23505');
select pg_temp.ok((select count(*)=0 from public.local_custody_policy_versions),'late writer version rollback');
select pg_temp.ok((select count(*)=1 from public.audit_ledger),'late writer ledger rollback');
select pg_temp.ok(pg_temp.cancel((select body from local149_saved where kind='cancel'),1)->'replayed'='true'::jsonb,'exact cancellation replay');
select pg_temp.cancel_refused(pg_temp.cancellation(161,(select body from local149_saved where kind='original'),'Changed reason'),1,'23505');
select pg_temp.refused(controller_security.canonical_questionnaire_json((select body::jsonb from local149_saved where kind='original')||jsonb_build_object('reason','Changed body')),1,'23505');
-- A spent cancellation key cannot become another policy intent or cancellation target.
select pg_temp.cancel_refused(pg_temp.cancellation(164,pg_temp.request(161,'request')),1,'23505');
do $$declare malformed text;begin
 foreach malformed in array array[controller_security.canonical_questionnaire_json(pg_temp.cancellation(165,pg_temp.request(65,'request'))::jsonb||jsonb_build_object('operationKey',null)),controller_security.canonical_questionnaire_json(pg_temp.cancellation(165,controller_security.canonical_questionnaire_json(pg_temp.request(65,'request')::jsonb||jsonb_build_object('operationKey',null)))::jsonb)] loop
  begin perform controller_security.local149_request(malformed);raise exception 'null operation accepted';exception when invalid_parameter_value then null;end;
 end loop;
end$$;
select pg_temp.ok(controller_security.local149_request(pg_temp.cancellation(168,pg_temp.request(68,'request'),repeat('😀',1500)))->>'reason'=repeat('😀',1500),'SQL matches Zod codepoint reason bound');
do $$begin begin perform controller_security.local149_request(pg_temp.cancellation(169,pg_temp.request(69,'request'),repeat('😀',2001)));raise exception 'oversized Unicode reason accepted';exception when invalid_parameter_value then null;end;end$$;
-- Record-first preserves exact143 response; cancellation cannot undo it.
insert into local149_saved values('recorded',pg_temp.request(62,'request'),null);
update local149_saved set v=pg_temp.write(body,1) where kind='recorded';
select pg_temp.ok(pg_temp.cancel(pg_temp.cancellation(162,(select body from local149_saved where kind='recorded')),1)->>'state'='recorded','record-first wins');
select pg_temp.ok((select count(*)=1 from public.local_custody_intent_cancellations),'record-first no tombstone');
-- Historical stale predecessor is cancellable without granting transition authority.
select pg_temp.ok(pg_temp.cancel(pg_temp.cancellation(163,pg_temp.request(63,'approve',pg_temp.id(999))),2)->>'state'='cancelled','stale head cancellation');
-- Current authority/session remains mandatory even for exact historical replay.
do $$begin begin update public.tenant_users set role='viewer' where tenant_id=pg_temp.id(11) and user_id=pg_temp.id(1);perform pg_temp.cancel((select body from local149_saved where kind='cancel'),1);raise exception 'retired actor accepted';exception when insufficient_privilege then null;end;end$$;
do $$begin begin update auth.sessions set not_after=clock_timestamp()-interval '1 second' where id=pg_temp.id(101);perform pg_temp.cancel((select body from local149_saved where kind='cancel'),1);raise exception 'expired session accepted';exception when insufficient_privilege then null;end;end$$;
select pg_temp.ok(not has_table_privilege('human_action_writer','public.local_custody_intent_cancellations','INSERT'),'no direct human inserts');
select pg_temp.ok(not has_function_privilege('service_role','public.record_local_custody_policy_cancellation(uuid,uuid,uuid,text,uuid)','EXECUTE'),'service cannot cancel');
select pg_temp.ok(not has_function_privilege('axiom_assessment_controller','public.record_local_custody_policy_cancellation(uuid,uuid,uuid,text,uuid)','EXECUTE'),'controller cannot cancel');
set constraints all immediate;set constraints all deferred;
do $$begin
 begin update public.local_custody_intent_cancellations set original_request_text='{}';raise exception 'immutable update accepted';exception when insufficient_privilege then null;end;
 begin delete from public.local_custody_intent_cancellations;raise exception 'immutable delete accepted';exception when insufficient_privilege then null;end;
 begin truncate public.local_custody_intent_cancellations;raise exception 'immutable truncate accepted';exception when insufficient_privilege then null;end;
end$$;
-- Naked ledger receipt and naked tombstone cannot commit; no orphan loophole.
do $$begin begin
 perform public.append_ledger(pg_temp.id(11),pg_temp.id(999),'human',pg_temp.id(1)::text,null,null,null,'custody.local_policy_intent_cancelled',pg_temp.id(998)::text,repeat('a',64),repeat('b',64),null,null,null,null,'success','{}');
 set constraints all immediate;raise exception 'orphan receipt accepted';exception when check_violation then null;end;end$$;

-- A forged tombstone with an existing unrelated human receipt must fail deferred reciprocity.
do $$declare body text:=pg_temp.cancellation(166,pg_temp.request(66,'request'));original text:=pg_temp.request(66,'request');begin begin
 insert into public.local_custody_intent_cancellations(id,tenant_id,actor_id,operation_key,original_operation_key,original_request_text,original_request_sha256,cancellation_text,cancellation_sha256,session_id,challenge_id,receipt_id)
 values(gen_random_uuid(),pg_temp.id(11),pg_temp.id(1),pg_temp.id(166),pg_temp.id(66),original,encode(sha256(convert_to(original,'UTF8')),'hex'),body,encode(sha256(convert_to(body,'UTF8')),'hex'),pg_temp.id(101),pg_temp.cancel_challenge(1,body),(select (v#>>'{receipt,id}')::bigint from local149_saved where kind='recorded'));
 set constraints all immediate;raise exception 'forged tombstone accepted';exception when check_violation then null;end;end$$;
-- A ledger append failure cannot leave an unaudited fence.
create function pg_temp.local149_fail_ledger() returns trigger language plpgsql as $$begin if new.action_type::text='custody.local_policy_intent_cancelled' then raise exception 'synthetic ledger failure' using errcode='P0001';end if;return new;end$$;
savepoint local149_ledger_failure;
create trigger local149_fixture_ledger_failure before insert on public.audit_ledger for each row execute function pg_temp.local149_fail_ledger();
do $$declare n bigint;begin select count(*) into n from public.local_custody_intent_cancellations;
 begin perform pg_temp.cancel(pg_temp.cancellation(167,pg_temp.request(67,'request')),1);raise exception 'ledger failure ignored';exception when raise_exception then if sqlerrm<>'synthetic ledger failure' then raise;end if;end;
 perform pg_temp.ok((select count(*)=n from public.local_custody_intent_cancellations),'ledger failure leaves no fence');end$$;
rollback to savepoint local149_ledger_failure;release savepoint local149_ledger_failure;
select pg_temp.ok((select count(*)=0 from public.verify_ledger(pg_temp.id(11))),'ledger chain preserved');
rollback;
